import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

cuda_decl = r"""
#include <torch/extension.h>
torch::Tensor batchnorm2d_forward(torch::Tensor x,
                                   torch::Tensor weight,
                                   torch::Tensor bias,
                                   torch::Tensor running_mean,
                                   torch::Tensor running_var,
                                   bool training,
                                   double momentum,
                                   double eps);
"""

cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>
#include <cute/tensor.hpp>

using namespace cute;

template <typename T, int BLOCK_THREADS>
__global__ void batchnorm2d_kernel(
    const T* __restrict__ X,
    T* __restrict__ Y,
    const T* __restrict__ weight,
    const T* __restrict__ bias,
    T* __restrict__ running_mean,
    T* __restrict__ running_var,
    int N, int C, int HW,
    float eps, float momentum, bool training)
{
    const int c = blockIdx.x;
    const int tid = threadIdx.x;
    const int nthreads = BLOCK_THREADS;

    const int64_t channel_stride = (int64_t)C * (int64_t)HW;

    // CUTE tensors viewing (N, HW) slice for this channel with NCHW strides
    auto gX = make_tensor(make_gmem_ptr(X + (int64_t)c * HW),
                           make_shape(N, HW),
                           make_stride(channel_stride, Int<1>{}));
    auto gY = make_tensor(make_gmem_ptr(Y + (int64_t)c * HW),
                           make_shape(N, HW),
                           make_stride(channel_stride, Int<1>{}));

    const int64_t total = (int64_t)N * (int64_t)HW;

    __shared__ float sdata_sum[BLOCK_THREADS];
    __shared__ float sdata_sq[BLOCK_THREADS];
    __shared__ float s_mean;
    __shared__ float s_var;

    float mean_f, var_f;

    if (training) {
        float sum = 0.f, sumsq = 0.f;
        for (int64_t idx = tid; idx < total; idx += nthreads) {
            int n  = (int)(idx / HW);
            int hw = (int)(idx % HW);
            float v = static_cast<float>(gX(n, hw));
            sum   += v;
            sumsq += v * v;
        }

        sdata_sum[tid] = sum;
        sdata_sq[tid]  = sumsq;
        __syncthreads();

        for (int s = nthreads / 2; s > 0; s >>= 1) {
            if (tid < s) {
                sdata_sum[tid] += sdata_sum[tid + s];
                sdata_sq[tid]  += sdata_sq[tid + s];
            }
            __syncthreads();
        }

        if (tid == 0) {
            float m = sdata_sum[0] / (float)total;
            float v = sdata_sq[0] / (float)total - m * m;
            if (v < 0.f) v = 0.f;
            s_mean = m;
            s_var  = v;

            float unbiased_var = (total > 1) ? (v * (float)total / (float)(total - 1)) : v;
            float old_rm = static_cast<float>(running_mean[c]);
            float old_rv = static_cast<float>(running_var[c]);
            running_mean[c] = static_cast<T>((1.f - momentum) * old_rm + momentum * m);
            running_var[c]  = static_cast<T>((1.f - momentum) * old_rv + momentum * unbiased_var);
        }
        __syncthreads();
        mean_f = s_mean;
        var_f  = s_var;
    } else {
        mean_f = static_cast<float>(running_mean[c]);
        var_f  = static_cast<float>(running_var[c]);
    }

    const float inv_std = rsqrtf(var_f + eps);
    const float w = static_cast<float>(weight[c]);
    const float b = static_cast<float>(bias[c]);

    for (int64_t idx = tid; idx < total; idx += nthreads) {
        int n  = (int)(idx / HW);
        int hw = (int)(idx % HW);
        float v = static_cast<float>(gX(n, hw));
        float y = (v - mean_f) * inv_std * w + b;
        gY(n, hw) = static_cast<T>(y);
    }
}

torch::Tensor batchnorm2d_forward(torch::Tensor x,
                                   torch::Tensor weight,
                                   torch::Tensor bias,
                                   torch::Tensor running_mean,
                                   torch::Tensor running_var,
                                   bool training,
                                   double momentum,
                                   double eps) {
    TORCH_CHECK(x.is_cuda(), "x must be CUDA");
    TORCH_CHECK(x.dim() == 4, "x must be 4D (N,C,H,W)");
    TORCH_CHECK(x.scalar_type() == at::kFloat, "x must be float32");

    auto x_c = x.contiguous();
    auto w_c = weight.contiguous();
    auto b_c = bias.contiguous();
    auto rm_c = running_mean.contiguous();
    auto rv_c = running_var.contiguous();

    int N = (int)x_c.size(0);
    int C = (int)x_c.size(1);
    int H = (int)x_c.size(2);
    int W = (int)x_c.size(3);
    int HW = H * W;

    auto y = torch::empty_like(x_c);

    constexpr int BLOCK_THREADS = 512;
    dim3 grid((unsigned)C);
    dim3 block(BLOCK_THREADS);

    cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();

    batchnorm2d_kernel<float, BLOCK_THREADS><<<grid, block, 0, stream>>>(
        x_c.data_ptr<float>(),
        y.data_ptr<float>(),
        w_c.data_ptr<float>(),
        b_c.data_ptr<float>(),
        rm_c.data_ptr<float>(),
        rv_c.data_ptr<float>(),
        N, C, HW,
        (float)eps, (float)momentum, training
    );

    auto err = cudaGetLastError();
    TORCH_CHECK(err == cudaSuccess, "batchnorm2d_kernel launch failed: ", cudaGetErrorString(err));

    // write back updated running stats (rm_c / rv_c may be new contiguous copies)
    if (training) {
        running_mean.copy_(rm_c);
        running_var.copy_(rv_c);
    }

    return y;
}
"""

bn_ext = load_inline(
    name="cute_batchnorm2d_ext",
    cpp_sources=cuda_decl,
    cuda_sources=cuda_src,
    functions=["batchnorm2d_forward"],
    extra_cflags=["-O3"],
    extra_cuda_cflags=["-O3"],
    extra_include_paths=["/root/cutegen_test/cutegen/cutlass/include"],
    verbose=False,
)


class ModelNew(nn.Module):
    """
    Batch Normalization implemented with a single custom CUTE/CUDA kernel.
    """
    def __init__(self, num_features: int):
        super().__init__()
        self.num_features = num_features
        self.eps = 1e-5
        self.momentum = 0.1

        self.weight = nn.Parameter(torch.ones(num_features))
        self.bias = nn.Parameter(torch.zeros(num_features))

        self.register_buffer("running_mean", torch.zeros(num_features))
        self.register_buffer("running_var", torch.ones(num_features))
        self.register_buffer("num_batches_tracked", torch.tensor(0, dtype=torch.long))

        self._ext = bn_ext

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        if self.training:
            self.num_batches_tracked += 1

        return self._ext.batchnorm2d_forward(
            x,
            self.weight,
            self.bias,
            self.running_mean,
            self.running_var,
            self.training,
            float(self.momentum),
            float(self.eps),
        )

